# Wyoming Statutes from the legislature's own Rocket NXT (Folio) publication at wyoleg.gov/NXT: its XML table of contents (f=xmlcontents getchildren) walked title -> chapter -> article (the Titles collection, plus Water = Title 99), each chapter/article document fetched once as HTML and cut at its <div class="Section"> headings; paragraphs are its Normal-Level blocks. (The title PDFs are cut off at 200k characters by the fetcher.)
import re
import xml.etree.ElementTree as ET
from urllib.parse import quote

GW = 'https://wyoleg.gov/NXT/gateway.dll'
HEAD = re.compile(r'^(\d+(?:\.\d+)?-\d+(?:\.\d+)?-\d+(?:\.\d+)*[A-Za-z]?)\.?\s*(.*)$')

def children(pid):
    url = GW + '?f=xmlcontents$command=getchildren$maxnodes=5000$minnodesleft=20$depth=1$basepathid=' + quote(pid, safe='')
    kind, body = fetch(url)
    nodes = ET.fromstring(body.encode('utf-8') if isinstance(body, str) else body).find('nodes')
    return [(n.get('ct'), n.get('id'), n.get('t') or '') for n in (nodes if nodes is not None else [])]

def documents(pid):
    for ct, nid, t in children(pid):
        if ct == 'text/xml':
            yield nid
        elif ct == 'application/folder':
            for d in documents(nid):
                yield d

def sections():
    years = [nid for ct, nid, t in children('') if re.match(r'^\d{4} Wyoming Statutes$', nid)]
    year = max(years)[:4]
    roots = ['%s Wyoming Statutes/%s %s' % (year, year, part) for part in ('Titles', 'Water')]   # Water = Title 99, noncodified statutes
    log('edition: %s' % roots)
    seen = set()
    for ct, tid, tname in [c for r in roots for c in children(r)]:
        n = 0
        for doc in documents(tid):
            url = GW + '/' + quote(doc, safe='/') + '?f=templates$fn=document-frame.htm$3.0'
            try:
                kind, page = fetch(url)
            except Exception as e:
                log('document failed %s: %s' % (doc, e)); continue
            for piece in page.split('<div class="Section">')[1:]:
                head = ' '.join(block_text('<div class="Section">' + piece, cls='Section').split())
                m = HEAD.match(head)
                if not m or m.group(1) in seen:
                    continue
                sid, heading = m.group(1), m.group(2).strip()
                paras = [' '.join(p.split()) for p in block_texts(piece, cls='Normal-Level')]
                text = '\n'.join(p for p in paras if p) or heading
                seen.add(sid); n += 1
                yield {'id': sid, 'heading': heading.rstrip('.').strip() or sid, 'text': text, 'url': url}
        log('%s: %d sections' % (tname, n))
